use std::time::Duration;

/// Parses a duration such as `90s`, `5m` or `2h`.
///
/// ```
/// use std::time::Duration;
/// assert_eq!(parse_duration("90s"), Ok(Duration::from_secs(90)));
/// ```
pub fn parse_duration(input: &str) -> Result<Duration, String> {
    let input = input.trim();
    let (num, unit) = input.split_at(input.len().saturating_sub(1));
    let n: u64 = num.parse().map_err(|_| format!("invalid duration: {input}"))?;
    match unit {
        "s" => Ok(Duration::from_secs(n)),
        "m" => Ok(Duration::from_secs(n * 60)),
        "h" => Ok(Duration::from_secs(n * 3600)),
        _ => Err(format!("unknown unit in duration: {input}")),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_seconds_minutes_hours() {
        assert_eq!(parse_duration("90s"), Ok(Duration::from_secs(90)));
        assert_eq!(parse_duration("5m"), Ok(Duration::from_secs(300)));
        assert_eq!(parse_duration("2h"), Ok(Duration::from_secs(7200)));
    }

    #[test]
    fn rejects_unknown_units() {
        assert!(parse_duration("3d").is_err());
        assert!(parse_duration("abc").is_err());
    }
}

