package com.acme.player.util

fun formatDuration(millis: Long): String {
    val totalSeconds = (millis / 1000).coerceAtLeast(0)
    val hours = totalSeconds / 3600
    val minutes = (totalSeconds % 3600) / 60
    val seconds = totalSeconds % 60
    return if (hours > 0) {
        "%d:%d:%02d".format(hours, minutes, seconds)
    } else {
        "%d:%02d".format(minutes, seconds)
    }
}

package com.acme.player.util

import org.junit.Assert.assertEquals
import org.junit.Test

class DurationFormatTest {
    @Test fun formatsMinutesAndSeconds() = assertEquals("4:02", formatDuration(242_000))
    @Test fun padsSeconds() = assertEquals("0:07", formatDuration(7_000))
    @Test fun formatsHoursMinutesSeconds() = assertEquals("1:05:09", formatDuration(3_909_000))
    @Test fun zeroIsZero() = assertEquals("0:00", formatDuration(0))
    @Test fun negativeClampsToZero() = assertEquals("0:00", formatDuration(-5_000))
}

